urlset:
{% spaceless %}
{% for url in urlset %}

    {{ url.location }}
    {% if url.lastmod %}{{ url.lastmod|date:"Y-m-d" }}{% endif %}
    {% if url.changefreq %}{{ url.changefreq }}{% endif %}
    {% if url.priority %}{{ url.priority }}{% endif %}
    {% for img in url.images %}
    {{ img.loc }}{% if img.title %}{{ img.title }}{% endif %}
    {% endfor %}

{% endfor %}
{% endspaceless %}
